-- Authored NES artwork overviews. Sources and floor mapping are documented in
-- project_resources/maps/descriptions/README.md. These are static impressions,
-- not current object reports or navigation instructions.
local maps = require "maps"
local darkness = require "darkness"
local M = {}

M.entries = {
    [0x02] = "Charlock's gray stone walls enclose a nearly symmetrical arrangement of red brick halls. Dark green ground surrounds the building, emphasizing its jagged outer edge. Three enclosed areas have striking blue and yellow diagonal stripes across their floors. A throne stands among gold squares at the far end of the central hall. Narrow openings connect the larger spaces, and small gray pillars interrupt the brickwork. The repeated shapes give the castle a stern, imposing appearance.",
    [0x03] = "Hauksness is a patchwork of broken gray walls, red brick floors, and pale sandy ground. The remains of rectangular buildings stand apart, with large gaps in their outlines. Grass spreads between them, dotted with little trees, while dark green patches cut uneven shapes into the brighter ground. Short stretches of brick paving end beside open sand. The scattered masonry makes the town look damaged and abandoned, with pieces of its former streets and rooms still recognizable.",
    [0x04] = "Tantegel is a large stone castle with red brick floors and broad rectangular rooms. Thick gray walls divide its halls, while strips of grass and small trees bring green into the interior. Blue water occupies much of the lower part of the castle, crossed by brick walkways and bridges. Striped blue and yellow floor panels stand out inside enclosed rooms. Straight corridors, squared corners, and repeated stone partitions give the castle a solid, ordered appearance.",
    [0x05] = "The throne room is a compact square enclosed by gray stone. Red brick covers most of the floor, while a band of gold squares marks the royal seating area near the back. A throne and small treasure boxes add finer detail to the simple tile patterns. The broad open floor contrasts with the thick enclosing walls. A doorway and a staircase break the room's otherwise regular outline, giving this small chamber a formal, ceremonial appearance.",
    [0x06] = "A sprawling gray stone complex stands amid bright blue water. Red brick chambers form a broad upper section, while a long gallery of repeating wall projections stretches down the western side. On the east, pale sandy banks and narrow green strips follow the water's irregular edge. Small arched bridges connect parts of this landscape. Gold floor squares mark a throne area within the masonry. The combination of enclosed halls and open shoreline makes this level feel unusually expansive.",
    [0x07] = "Kol is a wooded settlement with a broad sandy clearing through its middle. Dense rows of little green trees fill the spaces between gray stone buildings, sometimes lining up like hedges. Red brick paths lead into rooms of different sizes, their uneven outlines leaving small grassy pockets beside the walls. A bright blue bathing pool adds a splash of color near the northern buildings. Trees and open sand give the village a less enclosed appearance than the larger stone towns.",
    [0x08] = "Brecconary is a green town enclosed by gray stone walls. Broad paths of red brick divide grassy spaces dotted with small, tightly packed trees. Pale sandy clearings break up the green. Buildings appear as clusters of rectangular stone rooms with red brick floors and small signs beside some entrances. Blue water fills much of the southeastern quarter, narrowing into a winding channel crossed by small bridges. Enclosed buildings and open green spaces give the town an orderly appearance.",
    [0x09] = "A broad gray tiled roof dominates the northern half of Garinham. Its repeated rows of rounded tiles form a solid band above the smaller stone buildings below. Red brick lanes cross the southern part of town, passing grassy spaces and little trees. Blue water runs beside parts of the masonry, and small signs distinguish the public buildings. The large roof and compact rooms give Garinham a heavier, more tightly built appearance than an open village.",
    [0x0A] = "Cantlin is a densely built stone town laid out around a long central pool. Bright blue water curls around patches of grass and small clusters of trees, with a little arched bridge crossing the channel. Broad red brick streets separate blocks of gray rooms. Pale sandy courtyards open between some buildings, while narrow planted strips soften the straight walls. At the southern end, a rectangular enclosure filled with blue and yellow diagonal stripes adds a bold geometric pattern.",
    [0x0B] = "Rimuldar stands on bright green ground surrounded by winding blue channels. The water bends inward along the western side and curves around the buildings to the east. Small arched bridges connect the banks. Broad red brick paths spread between separate clusters of gray stone rooms, with trees lining some stretches and sandy patches beside the paving. The irregular shoreline breaks up the town's rectangular buildings, giving it the appearance of a settlement fitted among small waterways.",
    [0x0C] = "The Sun Shrine is a small gray stone chamber with a red brick floor. A central enclosure projects into the room, leaving broader stretches of brickwork around it. A small treasure box adds detail inside the recess, while the surrounding walls are mostly plain. The repeating brick lines and large square stones give the room a simple, solid appearance. Its few enclosed spaces make it feel more like a private cellar than a grand ceremonial hall.",
    [0x0D] = "The Rain Shrine is a compact square room built from gray stone and red brick. A broad brick passage frames a smaller central enclosure, making the walls look like one square set inside another. Short stone projections interrupt the inner room, creating little recesses and narrow openings. The surrounding masonry has the same repeating block pattern throughout. With few furnishings to break up the red and gray surfaces, the shrine has a plain, secluded appearance.",
    [0x0E] = "The Magic Temple is a small, nearly symmetrical stone shrine. Red brick covers the passages around a central gray enclosure. Matching groups of stone projections stand on either side, dividing the floor into narrow lanes and small pockets. Short brick stretches link these spaces into a balanced pattern. The few small furnishings sit within the central area, leaving most of the visual detail to the repeated stonework. Its paired shapes give the room a formal, carefully arranged appearance.",
    [0x0F] = "This basement is a broad square maze of red brick and gray stone. Long passages outline much of the floor, while interior walls divide it into smaller loops and bent corridors. A large solid block near the middle pushes the brick lanes around its sides. Elsewhere, short gray projections narrow the more open spaces. The uninterrupted red and gray patterns make the basement look heavier and more enclosed than the castle's striped halls above.",
    [0x10] = "This small basement looks like a red brick lattice woven through gray stone. Short vertical strips of floor meet crooked horizontal connections, with thick wall projections separating them into uneven pockets. A few tiny gray blocks stand within the brickwork rather than forming long partitions. The closely spaced corners fill almost the entire square floor. Without a broad central hall, the level has the appearance of many little pieces fitted tightly together.",
    [0x11] = "A long red brick strip runs along the bottom of this small square floor, while shorter passages fold around the stonework above it. Near the middle, gray walls form a jagged enclosure with small projections breaking its edges. The surrounding brick lanes bend sharply and vary in width. A broad outer stretch and a tightly divided center give the level two different visual rhythms, both drawn in the same red floor tiles and gray stone blocks.",
    [0x12] = "This compact basement has a strong rectangular outline of red brick near its upper and right edges. Inside, thick gray walls form a stepped, zigzag pattern, with shorter brick lanes winding between them. A hooked section of passage bends around a small patch of stone near the lower edge. The floor resembles a red angular drawing cut into a gray slab, with straight outer lines surrounding a much less regular center.",
    [0x13] = "Long parallel strips of red brick form a squared U around this small floor. Within it, gray stone walls wrap around a much tighter central pocket, creating the impression of one angular outline nested inside another. A few short connections interrupt the parallel lanes, but most of the floor is narrow and straight. The heavy square boundary and repeated inward turns give this basement a coiled appearance, like a simple pattern folded back on itself.",
    [0x14] = "A broad rectangular chamber of red brick dominates this basement. Gray stone surrounds its nearly unbroken floor, with only a few small projections interrupting the outline. A separate, thin horizontal passage lies above the chamber, divided from it by a thick band of masonry. The large red rectangle and narrow upper strip make a stark, simple composition. Compared with the other small castle basements, there are far fewer corners and interior partitions to catch the eye.",
    [0x15] = "Swamp Cave is shaped like a tall, narrow strip of gray stone threaded with red brick. Long vertical passages run beside one another, joined by short crosspieces that make a loose ladder-like pattern. Thick stone blocks fill the gaps, with a few wider floor pockets interrupting the narrow lanes. The same two tile patterns repeat along the cave's length. Its strongly elongated outline is more distinctive than any individual room or bend.",
    [0x16] = "The upper Mountain Cave floor is divided by long horizontal stretches of gray wall and red brick passage. Shorter vertical lanes connect these bands, giving parts of the square level a loosely layered appearance. Larger stone blocks near the edges enclose smaller pockets of brickwork. Toward the bottom, more frequent bends break up the straight lines. Red floor tiles stand out against the gray masonry, making the design look like a network of thin channels in solid rock.",
    [0x17] = "The lower Mountain Cave floor is a cluster of uneven red brick chambers among thick gray walls. Some rooms are broad enough to contain isolated stone blocks, while others narrow almost immediately into short passages. Wall projections break up the larger patches of floor, and a few tiny recesses sit between the more open spaces. The mixture of room sizes makes this floor look more irregular than the long horizontal bands of the level above.",
    [0x18] = "The upper grave floor is a large square maze with bright red brick lanes between heavy gray stone walls. Squared loops occupy some sections, while elsewhere long parallel passages meet shorter crossways. A few larger patches of floor interrupt the narrow lanes, and small doorways add detail to the masonry. The repeating walls divide the image into many enclosed pockets. Together, the straight lines and tightly packed corners give the floor the appearance of an elaborate stone labyrinth.",
    [0x19] = "A broad red brick border wraps around this grave floor's central stonework. Inside that outline, shorter passages and gray partitions form another compact arrangement of nested rectangles. Small isolated blocks interrupt parts of the inner floor, while the outer stretches remain long and straight. The whole level resembles a series of square frames fitted around one another. Its regular outline contrasts with the little breaks and recesses in the stonework near the middle.",
    [0x1A] = "This grave floor is a broad, crowded maze of red brick passages and gray stone. A long lane follows much of the outer edge, enclosing many staggered walls and small rectangular pockets. Inside, the brickwork repeatedly narrows, bends, and widens around projecting stone blocks. The uneven partitions interrupt the larger straight lines, making the center look particularly tangled. There is little empty space: nearly the entire square is filled with the repeated colors and corners of the maze.",
    [0x1B] = "The deepest grave floor is a little red brick chamber surrounded by a wide field of gray stone. Its stepped outline widens in the middle and narrows toward the top and bottom, forming a rough diamond. Small stone projections break up the center of the floor. The broad gray border emphasizes how small the chamber is. After the densely divided floors above, this simple, isolated shape has a strikingly spare appearance.",
    [0x1C] = "The upper floor of Erdrick's Cave is a small square maze of red brick paths and gray stone. A broad horizontal band of masonry divides the upper part from the more uneven passages below. Thick wall projections create little corners and pockets along the brick lanes. The floor has no large open hall; its character comes from the repeated short turns and solid blocks. The bright red paths make a crisp pattern against the plain gray walls.",
    [0x1D] = "The lower floor of Erdrick's Cave has an uneven arrangement of red brick corridors around thick gray walls. A broad central mass of stone separates smaller floor pockets, and a crooked passage wraps around its lower edge. Some stretches widen briefly before narrowing between wall projections. The small square boundary encloses a surprisingly varied red outline. Its asymmetrical pattern and few open spaces give the room a compact, secluded appearance, using the same plain masonry as the floor above.",
}

-- state_name is supplied by the existing field/battle/title detector. Physical
-- darkness, not the optional navigation policy, controls these overviews.
function M.describe(current, state_name)
    current = current or {}
    if state_name ~= "field" then
        return "Map description is unavailable outside field play", "not_field"
    end
    local description = M.entries[current.map_id]
    if not description then
        return "No map description is available here", "no_description"
    end
    local visibility = darkness.context(current)
    if visibility.limited and visibility.half_span == 0 then
        return "It is too dark to describe this dungeon. Use a Torch or cast Radiant first", "darkness"
    end
    return maps.get_name(current.map_id) .. ". " .. description, "available"
end

-- Shared by the physical hotkey and read-only command; never touches routes,
-- objects, RAM, or input. Existing gameplay speech can interrupt the paragraph.
function M.read(current, state_name)
    current = current or {}
    local message, result = M.describe(current, state_name)
    require("debug_tools").info(string.format("MAP_DESCRIPTION map=0x%02X result=%s: %s",
        current.map_id or 0, result, message))
    require("tolk").output(message)
end

return M
